('sylt-familien-inselzeit','Sylt mit Familie — Strand, Watt & Regentag-Plan B','Drei entspannte Inseltage für Familien: flacher Familienstrand in Wenningstedt, das Erlebnisbad und Aquarium in Westerland und die Naturgewalten-Ausstellung in List. Mit Schlechtwetter-Backup an jedem Ort.','https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=1400&h=700&fit=crop&auto=format&q=80',null,'PD24 Redaktion','public','completed',true,array['germany','family','beach','island','kids'],3,array['DE'],'family','medium',$$[{"lat":54.943,"lng":8.328,"nights":1,"citySlug":"sylt-wenningstedt","cityLabel":"Wenningstedt","planSummary":"Ruhiger Familienstrand mit flachem Einstieg, ein Steinzeit-Grab zum Staunen und die Heide zum Toben.","plannedStops":[{"hint":"Flacher Einstieg, Strandkörbe und breite Sandburgen-Zone","time":"10:00","label":"Familienstrand","itemName":"Strand Wenningstedt"},{"hint":"5000 Jahre alte begehbare Grabkammer — kleines Abenteuer für Kinder","time":"13:30","label":"Denghoog","itemName":"Denghoog Wenningstedt"},{"hint":"Leichter Rundweg durch Heide und Dünen mit Wattblick","time":"15:30","label":"Braderuper Heide","itemName":"Braderuper Heide"},{"hint":"Sonnenuntergang am Rutschenkliff mit Eis in der Hand","time":"18:00","label":"Eis am Kliff","itemName":"Wenningstedt Kliff"}]},{"lat":54.9079,"lng":8.305,"nights":1,"citySlug":"sylt-westerland","cityLabel":"Westerland","planSummary":"Der lebendige Hauptort: Erlebnisbad, Aquarium, Café Wien und die lange Strandpromenade — auch bei Regen ein voller Tag.","plannedStops":[{"hint":"Wellenbecken, Rutschen und Warmwasser direkt am Meer — der Regen-Retter","time":"10:00","label":"Sylter Welle","itemName":"Sylter Welle"},{"hint":"Traditionscafé mit großer Kuchenauswahl für die Mittagspause","time":"12:30","label":"Café Wien","itemName":"Café Wien Westerland"},{"hint":"Nordsee-Fische, Haie und ein Unterwassertunnel","time":"14:00","label":"Sylt Aquarium","itemName":"Sylt Aquarium"},{"hint":"Strandkörbe, Pommes und Drachensteigen bei Wind","time":"16:30","label":"Promenade & Musikmuschel","itemName":"Westerland Promenade"}]},{"lat":55.0189,"lng":8.4114,"nights":1,"citySlug":"sylt-list","cityLabel":"List","planSummary":"Hafenidylle mit Naturgewalten-Ausstellung, Fischbrötchen bei Gosch und einer Robben-Bootstour.","plannedStops":[{"hint":"Interaktive Mitmach-Ausstellung zu Watt, Wetter und Nordsee","time":"10:00","label":"Erlebniszentrum Naturgewalten","itemName":"Naturgewalten Sylt"},{"hint":"Fischbrötchen, Kutter und Softeis direkt am Wasser","time":"13:00","label":"Gosch am Lister Hafen","itemName":"Gosch List"},{"hint":"Seehunde auf den Sandbänken — Fernglas nicht vergessen","time":"15:00","label":"Robben-Bootstour","itemName":"Adler-Schiffe List"},{"hint":"Barfuß über die größte Wanderdüne der Insel","time":"17:00","label":"Wanderdüne","itemName":"Wanderdüne List"}]}]$$),
('sylt-girls-getaway','Sylt Girls Getaway — Kliff, Kunst & Champagner','Drei Tage Sylt für die beste Runde: Sonnenuntergang am Roten Kliff in Kampen, Shopping und Spa in Westerland, Galerien und Landhaus-Charme in Keitum. Viel Café, Prosecco und Meer.','https://images.unsplash.com/photo-1520250497591-112f2f40a3f4?w=1400&h=700&fit=crop&auto=format&q=80',null,'PD24 Redaktion','public','completed',true,array['germany','friends','wellness','island','girls-trip'],3,array['DE'],'friends','high',$$[{"lat":54.95,"lng":8.34,"nights":1,"citySlug":"sylt-kampen","cityLabel":"Kampen","planSummary":"Sylts glamouröse Seite: Panorama von der Uwe-Düne, Kuchen in der Kupferkanne, Rotes Kliff im Sonnenuntergang und Bubbles auf der Strönwai.","plannedStops":[{"hint":"Höchster begehbarer Punkt der Insel — 360°-Blick über Meer und Watt","time":"11:00","label":"Uwe-Düne","itemName":"Uwe Düne Kampen"},{"hint":"Kult-Café in einem alten Bunker mit riesigem Garten, legendärem Kuchen und Kupferkännchen-Kaffee","time":"13:00","label":"Kupferkanne","itemName":"Kupferkanne Kampen"},{"hint":"Spaziergang durchs Naturschutzgebiet hinauf zum Roten Kliff","time":"16:00","label":"Vogelkoje & Kliffweg","itemName":"Vogelkoje Kampen"},{"hint":"Der Sylt-Klassiker: rotglühendes Kliff im Abendlicht","time":"18:30","label":"Rotes Kliff Sunset","itemName":"Rotes Kliff Kampen"},{"hint":"Sundowner und Bubbles auf Kampens berühmter Whisky-Meile","time":"20:00","label":"Champagner auf der Strönwai","itemName":"Strönwai Kampen"}]},{"lat":54.9079,"lng":8.305,"nights":1,"citySlug":"sylt-westerland","cityLabel":"Westerland","planSummary":"Frühstück im Café Wien, Shopping auf der Friedrichstraße, ein langer Spa-Nachmittag und Dinner mit Meerblick im BeachHouse.","plannedStops":[{"hint":"Ausgiebiges Frühstück mit großer Auswahl zum entspannten Start","time":"10:00","label":"Frühstück Café Wien","itemName":"Café Wien Westerland"},{"hint":"Boutiquen, Sylt-Mode und Concept Stores in der Fußgängerzone","time":"11:30","label":"Friedrichstraße Shopping","itemName":"Friedrichstraße Westerland"},{"hint":"Thalasso, Sauna und Meerblick — der Wellness-Nachmittag, der immer passt","time":"14:00","label":"Syltness Center Spa","itemName":"Syltness Center"},{"hint":"Gehobene Küche mit direktem Meerblick zum Abschluss","time":"19:00","label":"Dinner im BeachHouse","itemName":"BeachHouse Sylt Westerland"}]},{"lat":54.893,"lng":8.365,"nights":1,"citySlug":"sylt-keitum","cityLabel":"Keitum","planSummary":"Ruhiger Ausklang: St. Severin, Galerien und Landhaus-Boutiquen, dazu Wein und gute Küche in der Reblaus.","plannedStops":[{"hint":"Historische Inselkirche und Kunsthandwerk in alten Friesenhäusern","time":"11:00","label":"St. Severin & Galerien","itemName":"St. Severin Keitum"},{"hint":"Interior, Schmuck und Sylt-Klassiker zum Mitnehmen","time":"13:30","label":"Landhaus-Boutiquen","itemName":"Keitum Boutiquen"},{"hint":"Ostfriesentee mit Blick auf die Wattkante am grünen Uferweg","time":"16:00","label":"Tee am Watt","itemName":"Keitumer Uferweg"},{"hint":"Gehobene Küche und gute Weine zum letzten Abend","time":"19:30","label":"Reblaus Wine & Dine","itemName":"Reblaus Keitum"}]}]$$),
('sylt-natur-slow-trail','Sylt Natur — Dünen, Watt & Weststrand','Drei Tage nur Natur: wandernde Dünen am Ellenbogen, das Wattenmeer bei Keitum und Seehundbänke an der Hörnum-Odde. Für alle, die Sylt langsam und wild erleben wollen.','https://images.unsplash.com/photo-1439066615861-d1af74d74000?w=1400&h=700&fit=crop&auto=format&q=80',null,'PD24 Redaktion','public','completed',true,array['germany','nature','beach','island','slow-travel'],3,array['DE'],'tourism','medium',$$[{"lat":55.0189,"lng":8.4114,"nights":1,"citySlug":"sylt-list","cityLabel":"List (Ellenbogen)","planSummary":"Nördlichster Punkt Deutschlands: wandernde Dünen am Ellenbogen, Wattblick am Königshafen und frischer Fisch bei Gosch.","plannedStops":[{"hint":"Landzunge mit Wanderdünen, zwei Leuchttürmen und dem nördlichsten Punkt Deutschlands","time":"09:30","label":"Ellenbogen","itemName":"Ellenbogen Sylt"},{"hint":"Ruhige Wattbucht mit Vögeln und Muschelbänken bei Ebbe","time":"12:00","label":"Königshafen","itemName":"Königshafen List"},{"hint":"Deutschlands nördlichster Fischimbiss — Fischbrötchen direkt am Wasser","time":"13:30","label":"Gosch am Kutterhafen","itemName":"Gosch List"},{"hint":"Über die höchste Wanderdüne der Insel zum weiten Sonnenuntergangsstrand","time":"18:30","label":"Wanderdüne & Weststrand","itemName":"Lister Weststrand"}]},{"lat":54.893,"lng":8.365,"nights":1,"citySlug":"sylt-keitum","cityLabel":"Keitum","planSummary":"Die grüne Seite: Wattenmeer-Wanderung, die alte St.-Severin-Kirche und friesische Küche bei Oma Wilma.","plannedStops":[{"hint":"Geführt ins Weltnaturerbe Wattenmeer — Priele, Wattboden und Wattwürmer","time":"09:30","label":"Wattwanderung","itemName":"Wattenmeer Keitum"},{"hint":"Historische Inselkirche aus dem 13. Jh. mit Blick über die grüne Insel","time":"13:00","label":"St. Severin","itemName":"St. Severin Keitum"},{"hint":"Schattige Wattallee, dann violette Heidelandschaft oberhalb der Küste","time":"15:00","label":"Grüner Uferweg & Braderuper Heide","itemName":"Braderuper Heide"},{"hint":"Bodenständige friesische Hausmannskost zum Ausklang","time":"19:00","label":"Oma Wilma Heimatküche","itemName":"Oma Wilma Keitum"}]},{"lat":54.757,"lng":8.296,"nights":1,"citySlug":"sylt-hoernum","cityLabel":"Hörnum","planSummary":"Die wilde Südspitze: Odde, Vogelparadies Rantumbecken, Seehundbänke und nordische Küche bei Lund.","plannedStops":[{"hint":"Sich ständig verändernde Landzunge mit Brandung, Dünen und Leuchtturm","time":"10:00","label":"Hörnum-Odde","itemName":"Hörnum Odde"},{"hint":"Naturschutzgebiet und Vogelparadies — Fernglas für Watvögel mitnehmen","time":"12:30","label":"Rantumbecken","itemName":"Rantumbecken"},{"hint":"Nordische Heimatküche, Zimtschnecken und Kaffee für die Mitte des Tages","time":"14:00","label":"Lund Sylt","itemName":"Lund Sylt Hörnum"},{"hint":"Zu den Sandbänken vor der Küste — Seehunde und Kegelrobben","time":"16:00","label":"Seehund-Bootstour","itemName":"Adler-Schiffe Hörnum"}]}]$$),
('sylt-nightlife-beach-party','Sylt Party — Whisky-Meile, Beach Clubs & Sansibar','Drei Nächte Sylt auf Vollgas: Bars und Strandclubs in Westerland, die legendäre Whisky-Meile in Kampen und Sundowner-Party an der Sansibar in Rantum. Für die Runde, die die Insel bei Nacht will.','https://images.unsplash.com/photo-1505142468610-359e7d316be0?w=1400&h=700&fit=crop&auto=format&q=80',null,'PD24 Redaktion','public','completed',true,array['germany','party','nightlife','island','beach-club'],3,array['DE'],'party','high',$$[{"lat":54.9079,"lng":8.305,"nights":1,"citySlug":"sylt-westerland","cityLabel":"Westerland","planSummary":"Warm-up an der Strandoase, Barhopping auf der Friedrichstraße und späte Clubnacht direkt am Meer.","plannedStops":[{"hint":"Aperol und Füße im Sand zum Sonnenuntergang am Hauptstrand","time":"18:30","label":"Sundowner Strandoase","itemName":"Strandoase Sylt Westerland"},{"hint":"Von der Weinbar zur Cocktailbar rund um die Fußgängerzone","time":"21:00","label":"Barhopping Friedrichstraße","itemName":"Westerland Bars"},{"hint":"Späte Nacht mit DJ und Blick auf die Brandung","time":"23:30","label":"Club am Meer","itemName":"Westerland Nightlife"}]},{"lat":54.95,"lng":8.34,"nights":1,"citySlug":"sylt-kampen","cityLabel":"Kampen","planSummary":"Der Sylt-Nightlife-Klassiker: Sundowner an der Sturmhaube, Whisky-Meile auf der Strönwai und die legendäre Pony Bar.","plannedStops":[{"hint":"Strandrestaurant am Roten Kliff — Sundowner mit Weitblick","time":"18:00","label":"Sturmhaube Sunset","itemName":"Sturmhaube Kampen"},{"hint":"Kampens berühmte Bar-Straße — von Bar zu Bar","time":"20:30","label":"Whisky-Meile Strönwai","itemName":"Strönwai Kampen"},{"hint":"Sylt-Institution mit Sägemehl am Boden und langer Nacht","time":"23:00","label":"Pony Bar","itemName":"Pony Bar Kampen"}]},{"lat":54.85,"lng":8.29,"nights":1,"citySlug":"sylt-rantum","cityLabel":"Rantum","planSummary":"Finale an der Sansibar: durch die Dünen zum Kult-Strandlokal, Sundowner und Beach-Club-Stimmung bis spät.","plannedStops":[{"hint":"Über die Rantumer Dünen zum berühmtesten Strandlokal der Insel","time":"17:00","label":"Dünen-Anmarsch","itemName":"Rantum Dünen"},{"hint":"Wein, Austern und Sonnenuntergang an der Kult-Location zwischen den Dünen","time":"18:30","label":"Sansibar","itemName":"Sansibar Rantum"},{"hint":"Musik, Sand und der letzte Drink unter Sternen","time":"21:00","label":"Beach-Club-Ausklang","itemName":"Rantum Beach"}]}]$$)
